#!/bin/bash
#
# This scripts executes UUT (Unity Unit Test) suite.
# The test cases are maintained in test/uut directory.
#
# All optional script arguments passed to ceedling build tool as-is.
# Default target: "clobber gcov:all utils:gcov"
# clobber - cleanup output directory
# gcov:all - build and run all test cases, collect coverage data
# utils:gcov - generate coverage report
#
# https://confluencewikiprod.intra.infineon.com/x/B41wF
# http://www.throwtheswitch.org/ceedling
# https://github.com/ThrowTheSwitch/Ceedling/blob/master/docs/CeedlingPacket.md

build_dir="$(dirname "${BASH_SOURCE[0]}")"
source "$build_dir/setenv.sh"

set -$-ue${DEBUG+xv}

# Download third-party toolchains
download_deps

# Download and extract the dependent assets
fetch_corelib
fetch_pdl_cat1
fetch_cmsis_dsp
#fetch_cmsis_5
fetch_sensor_dsp

# Set path to the CMSIS libraries
export CMSIS_DIR="$OUT_DIR/libs/cmsis-dsp/CMSIS-DSP-1.10.1"
#export CMSIS_5_DIR="$OUT_DIR/libs/cmsis-5/CMSIS_5-5.9.0"
export PDL_DIR="$OUT_DIR/libs/mtb-pdl-cat1/"
export SENSOR_DSP_DIR="$OUT_DIR/libs/sensor-dsp"

# Log is needed to detect the ceedling error
uut_out_dir="$OUT_DIR/test/uut"
ceedling_log="$uut_out_dir/ceedling.log"
rm -rf "$uut_out_dir"/*
mkdir -p "$uut_out_dir/gcov"

# Install python modules required by ceedling
setup_python_env
"$PYTHON" --version

# Add ruby, ceedling and gcc to PATH
case "$KERNEL" in
    CYGWIN*|MINGW*|MSYS*)
        # Expect Ruby 2.7 interpreter + DevKit (x86) installed by RubyInstaller at the default location
        command -v ruby >/dev/null 2>&1 || export PATH="$(cygpath --unix "C:/Ruby27/bin"):$PATH"
        command -v gcc  >/dev/null 2>&1 || export PATH="$(cygpath --unix "C:/Ruby27/msys32/mingw32/bin"):$PATH"
        # Print diagnostic information
        [[ -n "${CI:-}" ]] && echo PATH=$PATH
        where ruby ceedling gcc gcov gcovr
        # execute batch file to avoid passing cygwin path to ruby.exe
        ceedling=ceedling.bat
        ;;
    *)
        [[ -n "${CI:-}" ]] && echo PATH=$PATH
        which ruby ceedling gcc gcov gcovr
        ceedling=ceedling
        ;;
esac

cd "$ROOT_DIR/test/uut"

# Pass all script arguments ($@) to the ceedling tool
ceedling_args=$@

# Execute the default tasks when no arguments passed:
# ceedling clobber gcov:all utils:gcov
# This compile and executes all tests, creates *.gcda, *.gcno, *.gcov files
[[ -z "$ceedling_args" ]] && ceedling_args="clobber gcov:all utils:gcov"

# Execute ceedling tool, store the stdout in uut.log
$ceedling $ceedling_args | tee "$ceedling_log"

# Parse the ceedling log to determine the number of the failed test cases
test_status=$(grep ' FAILED TESTS' "$ceedling_log" | head -1)
test_status_regex='([0-9]+) FAILED TESTS'
if [[ $test_status =~ $test_status_regex ]]; then
    error_count=${BASH_REMATCH[1]}
else
    echo "ERROR: unit test suite was not executed, check the ceedling log"
    exit 1
fi

# Rename gcovr generated gcov files to remove '^#^#' prefix
_prefix='^#^#'
for _file in '^#^#'*; do mv "$_file" "${_file#$_prefix}"; done

# Discover relevant *.gcov files generated by gcovr
# Ignore the gcov files generated for tests, stubs and mocks
# The below list of find exclude patterns matches project.yml, gcovr report_exclude setting
gcov_files=$(find . -maxdepth 1 -type f -name "*.gcov" \
    ! \( -name "output#*" -o -name "build#*" -o -name "stubs#*" -o -name "test_*" -o -name "*.h.gcov" \))

# Create zip file with the relevant *.gcov files
rm -f "$uut_out_dir/lin_uut_gcov.zip"
if [[ -n "$gcov_files" ]]; then
    zip "$uut_out_dir/lin_uut_gcov.zip" $gcov_files
fi
# Delete all *.gcov files generated by gcovr
rm -f *.gcov

# Copy interesting artifacts to the output directory
# unity/gcovr generated logs and junit report.xml - to output/test/uut
# gcovr generated html coverage reports - to output/test/uut/gcov
find build/artifacts/gcov -type f \( -name "*.xml" -o -name "*.log" \) -exec mv {} "$uut_out_dir" \;
find build/artifacts/gcov -type f -name "*.html" -exec mv {} "$uut_out_dir/gcov" \;

# Output the gcovr text summary into the console log
if [[ -f "$uut_out_dir/gcovr.log" ]]; then
    cat "$uut_out_dir/gcovr.log"
else
    echo "ERROR: coverage report was not generated, check the ceedling log"
fi

# Report the ceedling error count (0 == success)
echo $test_status
exit $error_count
